 7	endmodule
 1	module g06_priority_decode(
 2	  input  logic [7:0] request,
 3	  output logic [2:0] index,
 4	  output logic       valid
 5	);
 6	  always_comb begin
 7	    index = 3'd0;
 8	    valid = 1'b1;
 9	    if      (request[7]) index = 3'd7;
10	    else if (request[6]) index = 3'd6;
11	    else if (request[5]) index = 3'd5;
12	    else if (request[4]) index = 3'd4;
13	    else if (request[3]) index = 3'd3;
14	    else if (request[2]) index = 3'd2;
15	    else if (request[1]) index = 3'd1;
16	    else if (request[0]) index = 3'd0;
17	    else                 valid = 1'b0;
18	  end
19	endmodule
