 1	module g03_mixed_safe_add(
 2	  input  logic [15:0] a, b, c, d,
 3	  input  logic [1:0]  sel,
 4	  output logic [15:0] sum,
 5	  output logic [15:0] picked
 6	);
 7	  assign sum = ((a + b) + c) + d;
 8	  always_comb begin
 9	    case (sel)
10	      2'd0: picked = a;
11	      2'd1: picked = b;
12	      2'd2: picked = c;
13	      default: picked = d;
14	    endcase
15	  end
16	endmodule
 1	module g04_mixed_procedural_add(
 2	  input  logic [15:0] a, b, c, d,
 3	  input  logic        bypass,
 4	  output logic [15:0] y
 5	);
 6	  always_comb begin
 7	    if (bypass)
 8	      y = a;
 9	    else
10	      y = ((a + b) + c) + d;
11	  end
12	endmodule

